/**
 * Release-date helpers for YouTube tracks.
 *
 * Official YouTube Music tracks ("Artist - Topic" uploads, auto-generated by
 * YouTube) have a description like:
 *
 *   Provided to YouTube by Asylum
 *
 *   Hotel California (2013 Remaster) · Eagles
 *
 *   Hotel California
 *
 *   ℗ 1976 Elektra/Asylum Records
 *
 *   Released on: 1976-12-08
 *
 *   Auto-generated by YouTube.
 *
 * "Released on" is the release date of that particular album/edition; ℗ is
 * the phonographic copyright year. Either is far closer to the real release
 * year than the upload date.
 */

const MIN_YEAR = 1900;

function isPlausibleYear(year: number, now = new Date()): boolean {
  return year >= MIN_YEAR && year <= now.getUTCFullYear() + 1;
}

/** Normalises "YYYY", "YYYY-MM" or "YYYY-MM-DD" (MusicBrainz style) dates. */
export function normalizeDate(value: string | undefined | null): string | null {
  const match = /^(\d{4})(?:-(\d{2}))?(?:-(\d{2}))?/.exec(value?.trim() ?? "");
  if (!match) return null;
  const year = Number(match[1]);
  if (!isPlausibleYear(year)) return null;
  return [match[1], match[2], match[3]].filter(Boolean).join("-");
}

export function parseReleaseDateFromDescription(
  description: string | undefined | null,
): string | null {
  if (!description) return null;

  const released = /Released on:\s*(\d{4}-\d{2}-\d{2})/i.exec(description);
  if (released) {
    const date = normalizeDate(released[1]);
    if (date) return date;
  }

  // ℗ (sound recording copyright). Some descriptions use "(P)" instead.
  const phonogram = /(?:℗|\(P\))\s*(\d{4})/.exec(description);
  if (phonogram) {
    const date = normalizeDate(phonogram[1]);
    if (date) return date;
  }

  return null;
}

// Noise commonly appended to music video titles. Applied repeatedly.
const TITLE_NOISE = [
  /\s*[([](?:official|offical)?\s*(?:hd|hq|4k|8k)?\s*(?:music\s*video|video\s*clip|video|audio|lyric(?:s)?(?:\s*video)?|visuali[sz]er|live|remaster(?:ed)?(?:\s*\d{4})?|\d{4}\s*remaster(?:ed)?|explicit|clean|full\s*album)[^)\]]*[)\]]/gi,
  /\s*[([](?:hd|hq|4k|8k|official)[)\]]/gi,
  /\s*[([](?:ft|feat|featuring)\.?\s[^)\]]*[)\]]/gi,
  /\s+(?:ft|feat|featuring)\.?\s.+$/i,
  /\s*\|.*$/,
];

const ARTIST_NOISE = [/\s*-\s*Topic$/i, /VEVO$/i, /\s*Official$/i];

export function cleanArtistName(channelTitle: string): string {
  let name = channelTitle.trim();
  for (const pattern of ARTIST_NOISE) name = name.replace(pattern, "").trim();
  return name;
}

/**
 * Best-effort (artist, title) for a lookup. Music video titles are often
 * "Artist - Song (Official Video)", in which case the title's artist wins
 * over the uploading channel (which may be a label).
 */
export function cleanTrackForLookup(
  rawTitle: string,
  channelTitle: string,
): { artist: string; title: string } {
  let title = rawTitle.trim();
  for (const pattern of TITLE_NOISE) title = title.replace(pattern, "").trim();

  let artist = cleanArtistName(channelTitle);

  const split = /^(.+?)\s+[-–—]\s+(.+)$/.exec(title);
  if (split) {
    artist = split[1].trim();
    title = split[2].trim();
    for (const pattern of TITLE_NOISE) title = title.replace(pattern, "").trim();
  }

  title = title.replace(/^["“']|["”']$/g, "").trim();
  return { artist, title };
}
